"""B1 exact enumeration of a real native discrete/continuous future-teaching gradient."""
import argparse,hashlib,json,resource,time
from pathlib import Path
import torch
from torch.func import functional_call
import run_native_trusted_operator_credit as run
from operator_event_credit import local_vjp

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--tag',required=True);a=ap.parse_args();root=run.ROOT;out=root/f'experiments/results/credit/{a.tag}.json';assert not out.exists();start=time.monotonic();torch.set_num_threads(1);torch.set_default_dtype(torch.float64);run.RUN_WIDTH=8;run.extension();actor=run.initial(99910,4,10,1.,[-1.,0.,1.]);data=[s for s in run.native.load_split('taxi','train') if len(s[1])>=32];K=1+max(int(m.max()) for _,m in data);actor=run.initial(99910,4,K,1.,[-1.,0.,1.]);run.install_event_hooks(actor);actor.collect_events=True;actor.cut=True;t,m,mask=run.one_block(data[1328]);loss=actor(t,m,mask);c=torch.autograd.grad(loss,actor.terminal)[0];p=run.context(actor,c,loss,t);field=run.new_credit(actor,4)
    with torch.no_grad():
        for decoder in field.decoders.values():decoder.weight.normal_(0,.02);decoder.bias.normal_(0,.01)
        field.query.weight.normal_(0,.02)
    tf,mf,mfmask=run.one_block(data[1329]);actor.cut=False;actor.collect_events=False
    with torch.no_grad():baseline=actor(tf,mf,mfmask)
    # Independent native one-event forward with incoming temporal memory held fixed.
    ids=torch.tensor([16,24]);prefix='layers.3.';operators={n[len(prefix):]:v.detach().clone().requires_grad_() for n,v in p['operators'].items() if n.startswith(prefix)};u=p['inputs'][prefix+'write.weight'][ids].detach().clone().requires_grad_();allz=p['inputs'][prefix+'read.weight'];prior=torch.cat([allz.new_zeros(1,allz.shape[1]),allz[:-1]],0)[ids].detach();dt=p['dt'][ids];N=4;linear=lambda x,n:x@operators[n+'.weight'].T+operators[n+'.bias'];write=linear(u,'write');gate=torch.sigmoid(linear(u,'gate'));cr=torch.exp(-operators['log_rate'].exp()*dt[:,None])*torch.cos(operators['freq']*dt[:,None]);ci=torch.exp(-operators['log_rate'].exp()*dt[:,None])*torch.sin(operators['freq']*dt[:,None]);z=torch.cat([cr*prior[:,:N]-ci*prior[:,N:],cr*prior[:,N:]+ci*prior[:,:N]],-1)+write*torch.cat([gate,gate],-1);h=torch.nn.functional.layer_norm(u+linear(z,'read'),(8,),operators['norm1.weight'],operators['norm1.bias']);output=torch.nn.functional.layer_norm(h+linear(torch.nn.functional.gelu(linear(h,'mlp.0')),'mlp.2'),(8,),operators['norm2.weight'],operators['norm2.bias']);cotangent=p['cotangent'][ids];target=(output*cotangent).sum()/len(ids);names=list(operators);autograds=torch.autograd.grad(target,[u]+[operators[n] for n in names]);cu,analytic=local_vjp(u.detach(),z.detach(),dt,{n:v.detach() for n,v in operators.items()},cotangent);local_errors=[float((cu/len(ids)-autograds[0]).abs().max())]+[float((analytic[n]-g).abs().max()) for n,g in zip(names,autograds[1:])];local_error=max(local_errors);assert local_error<1e-10,local_error
    values=[];logs=[];pool=torch.tensor([16,24]);named=dict(actor.named_parameters())
    for chosen in pool:
        direction=field(p,forced=[chosen],pool=pool);issued,_=field.propose(named,direction);assert float(field.last_step_deviation)<=float(field.last_trust_bound)+1e-12;values.append(functional_call(actor,issued,(tf,mf,mfmask)));logs.append(field.last_logprob)
    probs=torch.stack(logs).exp();assert abs(float(probs.sum().detach())-1)<1e-12;exact=sum(pr*l for pr,l in zip(probs,values));surrogate=sum(pr.detach()*(l+(l.detach()-baseline)*lp) for pr,l,lp in zip(probs,values,logs));params=list(field.parameters());g1=torch.autograd.grad(exact,params,retain_graph=True,allow_unused=True);g2=torch.autograd.grad(surrogate,params,allow_unused=True);errors=[float((x-y).abs().max()) for x,y in zip(g1,g2) if x is not None and y is not None];error=max(errors);contrast=abs(float((values[0]-values[1]).detach()));query_index=next(i for i,x in enumerate(params) if x is field.query.weight);query_norm=float(g1[query_index].norm());gate=error<1e-10 and local_error<1e-10 and contrast>1e-10 and query_norm>1e-12;assert gate,(error,contrast,query_norm)
    sources=['experiments/credit/check_trusted_operator_credit.py','experiments/credit/run_native_trusted_operator_credit.py','experiments/credit/trusted_operator_credit.py','experiments/credit/NATIVE_TRUSTED_OPERATOR_PROTOCOL.md','experiments/credit/operator_event_credit.py','experiments/credit/batched_event_parameter_credit.py','experiments/credit/run_native_operator_event_credit.py','experiments/credit/NATIVE_OPERATOR_EVENT_CREDIT_PROTOCOL.md','experiments/credit/event_optimizer_credit.py','experiments/credit/run_native_event_optimizer.py','experiments/credit/NATIVE_EVENT_OPTIMIZER_PROTOCOL.md','experiments/credit/event_parameter_credit.py','experiments/credit/run_native_event_credit.py','experiments/credit/NATIVE_EVENT_CREDIT_PROTOCOL.md','experiments/tpp/race_tpp_v19.py','experiments/tpp/temporal_scan_cpu.py','experiments/tpp/temporal_scan_cpu.cpp'];record=dict(status='completed',battle='B1',tag=a.tag,gate=gate,max_gradient_error=error,local_adjoint_max_error=local_error,future_loss_contrast=contrast,query_gradient_norm=query_norm,probability_sum=float(probs.sum().detach()),wall_s=time.monotonic()-start,peak_rss_kb=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,source_sha256={s:hashlib.sha256((root/s).read_bytes()).hexdigest() for s in sources},scope='Real native depth4,width8 Taxi TRAIN; two enumerated single-event query actions, local finite update expectation only. Algebra check, no learning utility claim.');out.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record),flush=True)
